<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import FieldError from '../../../components/FieldError.vue';
import StatusNotice from '../../../components/StatusNotice.vue';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string }
interface FulfillmentItem { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; inventory_reservation_id: string; unit_cost_snapshot?: string | null; cogs_amount?: string | null; cost_currency?: string | null }
interface Shipment { id: string; status: string; carrier: string | null; carrier_name: string | null; service_name: string | null; tracking_number: string | null; tracking_url: string | null; ready_at: string | null; shipped_at: string | null; delivered_at: string | null; can_ready: boolean; can_ship: boolean; can_deliver: boolean; can_cancel: boolean; history: History[] }
interface Fulfillment { id: string; order_id: string; order_number: string; status: string; location_name: string; location_code: string; items: FulfillmentItem[]; history: History[]; shipments: Shipment[]; started_at: string | null; completed_at: string | null; cancelled_at: string | null; cancellation_reason?: string | null; created_at: string }
interface Capabilities { manage: boolean; complete: boolean; shipments_manage: boolean; start: boolean; cancel: boolean; create_shipment: boolean; complete_action: boolean }
interface Eligibility { eligible: boolean; reason: string | null }

const props = defineProps<{ fulfillment: Fulfillment; capabilities: Capabilities; paymentEligibility: Eligibility }>();
const { t, te, locale } = useI18n();
const page = usePage<PageProps>();
const noticeKeys: Record<string, string> = {
    'Fulfillment created.': 'created', 'Fulfillment started.': 'started', 'Fulfillment completed and inventory committed.': 'completed', 'Fulfillment cancelled.': 'cancelled',
    'Shipment created.': 'shipmentCreated', 'Shipment marked ready.': 'shipmentReady', 'Shipment marked shipped.': 'shipmentShipped', 'Shipment marked delivered.': 'shipmentDelivered', 'Shipment cancelled.': 'shipmentCancelled',
};
const errorKeys: Record<string, string> = {
    'Only a pending fulfillment can be started.': 'startState', 'A fulfilled fulfillment cannot be cancelled.': 'cancelState', 'A cancelled fulfillment cannot be shipped.': 'cancelledShipment', 'Shipments can only be created for shipping orders.': 'shippingOnly', 'Only a shipped shipment can be delivered.': 'deliverState', 'Only a pending shipment can be marked ready.': 'readyState', 'Only a ready shipment can be shipped.': 'shipState', 'The fulfillment must be fulfilled before shipment.': 'fulfillmentFirst', 'A shipped or delivered shipment cannot be cancelled.': 'shipmentCancelState', 'Only a processing fulfillment for a confirmed order can be completed.': 'completeState', 'The fulfillment inventory allocation is incomplete.': 'allocationIncomplete', 'A fulfillment allocation is no longer valid or available.': 'allocationUnavailable',
};
const statusNotice = computed(() => {
    const status = page.props.status;
    if (!status) return undefined;
    const key = noticeKeys[status];
    return key ? t(`fulfillment.notices.${key}`) : status;
});
const errors = computed(() => page.props.errors as Record<string, string | undefined>);
const totalUnits = computed(() => props.fulfillment.items.reduce((total, item) => total + item.quantity, 0));
const exposesCosts = computed(() => props.fulfillment.items.some((item) => item.cogs_amount !== undefined));
const activeAction = ref<string | null>(null);
const cancellingShipment = ref<string | null>(null);
const fulfillmentCancelForm = useForm({ reason: '' });
const shipmentCancelForm = useForm({ reason: '' });
const shipmentForm = useForm({ carrier_name: '', service_name: '', tracking_number: '', tracking_url: '' });
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : t('common.notAvailable');
const localizedError = (message?: string) => message && errorKeys[message] ? t(`fulfillment.errors.${errorKeys[message]}`) : message;
const eligibilityReason = computed(() => props.paymentEligibility.reason && te(`fulfillment.eligibility.${props.paymentEligibility.reason}`) ? t(`fulfillment.eligibility.${props.paymentEligibility.reason}`) : props.paymentEligibility.reason);
const postFulfillment = (action: 'start' | 'complete') => {
    if (activeAction.value) return;
    activeAction.value = action;
    router.post(`/admin/fulfillments/${props.fulfillment.id}/${action}`, {}, { preserveScroll: true, onFinish: () => { activeAction.value = null; } });
};
const cancelFulfillment = () => {
    if (!window.confirm(t('fulfillment.cancelConfirm'))) return;
    fulfillmentCancelForm.post(`/admin/fulfillments/${props.fulfillment.id}/cancel`, { preserveScroll: true });
};
const createShipment = () => shipmentForm.post(`/admin/fulfillments/${props.fulfillment.id}/shipment`, { preserveScroll: true, onSuccess: () => shipmentForm.reset() });
const shipmentAction = (shipment: Shipment, action: 'ready' | 'ship' | 'deliver') => {
    const key = `${shipment.id}:${action}`;
    if (activeAction.value || !window.confirm(t(`fulfillment.${action}Confirm`))) return;
    activeAction.value = key;
    router.post(`/admin/shipments/${shipment.id}/${action}`, {}, { preserveScroll: true, onFinish: () => { activeAction.value = null; } });
};
const openShipmentCancellation = (shipment: Shipment) => { cancellingShipment.value = shipment.id; shipmentCancelForm.reset(); shipmentCancelForm.clearErrors(); };
const cancelShipment = (shipment: Shipment) => shipmentCancelForm.post(`/admin/shipments/${shipment.id}/cancel`, { preserveScroll: true, onSuccess: () => { cancellingShipment.value = null; shipmentCancelForm.reset(); } });
</script>

<template>
    <Head :title="t('fulfillment.detailTitle', { order: fulfillment.order_number })" />
    <AdminLayout><div class="space-y-6">
        <Breadcrumbs :items="[{ label: t('nav.operations') }, { label: t('fulfillment.title'), href: '/admin/fulfillments' }, { label: fulfillment.order_number }]" />
        <PageHeader :title="t('fulfillment.detailTitle', { order: fulfillment.order_number })" :eyebrow="t('fulfillment.operationalRecord')" :description="t('fulfillment.detailDescription', { date: formatDate(fulfillment.created_at) })"><template #actions><Link :href="`/admin/orders/${fulfillment.order_id}`" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold hover:bg-slate-50">{{ t('fulfillment.openOrder') }}</Link></template></PageHeader>
        <StatusNotice :message="statusNotice" />

        <section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" :aria-label="t('fulfillment.summary')">
            <article class="admin-card p-3"><p class="admin-label">{{ t('common.status') }}</p><div class="mt-2"><StatusBadge :status="fulfillment.status" /></div></article>
            <article class="admin-card p-3"><p class="admin-label">{{ t('fulfillment.location') }}</p><p class="mt-1 font-mono text-sm font-semibold">{{ fulfillment.location_code }}</p><p class="text-xs text-admin-neutral">{{ fulfillment.location_name }}</p></article>
            <article class="admin-card p-3"><p class="admin-label">{{ t('fulfillment.units') }}</p><p class="mt-1 font-mono text-lg font-semibold tabular-nums">{{ totalUnits }}</p><p class="text-xs text-admin-neutral">{{ t('fulfillment.lineCount', { count: fulfillment.items.length }) }}</p></article>
            <article class="rounded-lg border p-3" :class="paymentEligibility.eligible ? 'border-admin-success-border bg-admin-success-bg' : 'border-admin-warning-border bg-admin-warning-bg'"><p class="admin-label">{{ t('fulfillment.paymentGate') }}</p><p class="mt-1 text-sm font-semibold">{{ paymentEligibility.eligible ? t('fulfillment.eligible') : t('fulfillment.blocked') }}</p><p v-if="eligibilityReason" class="mt-1 text-xs">{{ eligibilityReason }}</p></article>
        </section>

        <section v-if="capabilities.start || capabilities.complete_action" class="admin-card flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="admin-label text-admin-secondary">{{ t('fulfillment.nextOperation') }}</p><p class="mt-1 text-sm text-admin-neutral">{{ t('fulfillment.operationHelp') }}</p></div><div class="grid gap-2 sm:flex"><button v-if="capabilities.start" :disabled="Boolean(activeAction)" class="rounded-md bg-admin-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50" @click="postFulfillment('start')">{{ activeAction === 'start' ? t('fulfillment.processing') : t('fulfillment.start') }}</button><button v-if="capabilities.complete_action" :disabled="!paymentEligibility.eligible || Boolean(activeAction)" class="rounded-md border border-admin-success-border bg-admin-success-bg px-4 py-2.5 text-sm font-semibold text-admin-success disabled:cursor-not-allowed disabled:opacity-40" @click="postFulfillment('complete')">{{ activeAction === 'complete' ? t('fulfillment.processing') : t('fulfillment.complete') }}</button></div></section>
        <FieldError :message="localizedError(errors.fulfillment ?? errors.payment ?? errors.reservation ?? errors.shipment)" />

        <section class="grid gap-5 lg:grid-cols-[minmax(0,3fr)_minmax(18rem,2fr)]">
            <div class="min-w-0"><div><p class="admin-label text-admin-secondary">{{ t('fulfillment.itemsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('fulfillment.pickList') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('fulfillment.pickListHelp') }}</p></div>
                <div class="admin-card mt-4 hidden overflow-hidden sm:block"><table class="admin-table w-full table-fixed text-left text-xs"><thead><tr><th class="w-[43%] p-3">{{ t('fulfillment.item') }}</th><th class="w-[22%] p-3">{{ t('fulfillment.sku') }}</th><th class="w-[15%] p-3 text-right">{{ t('fulfillment.quantity') }}</th><th v-if="exposesCosts" class="w-[20%] p-3 text-right">{{ t('fulfillment.cost') }}</th></tr></thead><tbody class="divide-y divide-admin-border"><tr v-for="item in fulfillment.items" :key="item.id"><td class="p-3"><p class="font-semibold">{{ item.product_name }}</p><p class="mt-0.5 text-admin-neutral">{{ item.variant_name ?? t('fulfillment.defaultVariant') }}</p></td><td class="p-3 font-mono">{{ item.sku }}</td><td class="p-3 text-right font-mono font-semibold">{{ item.quantity }}</td><td v-if="exposesCosts" class="p-3 text-right font-mono"><span v-if="item.unit_cost_snapshot !== null && item.unit_cost_snapshot !== undefined">{{ item.cost_currency }} {{ item.unit_cost_snapshot }}<span class="block text-[10px] text-admin-neutral">{{ t('fulfillment.cogs') }} {{ item.cost_currency }} {{ item.cogs_amount }}</span></span><span v-else class="text-admin-neutral">{{ t('fulfillment.costUnavailable') }}</span></td></tr></tbody></table></div>
                <div class="mt-4 grid gap-2.5 sm:hidden"><article v-for="item in fulfillment.items" :key="`mobile-${item.id}`" class="admin-card p-3.5"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="text-sm font-semibold">{{ item.product_name }}</p><p class="mt-0.5 text-xs text-admin-neutral">{{ item.variant_name ?? t('fulfillment.defaultVariant') }}</p></div><strong class="font-mono text-lg">{{ item.quantity }}</strong></div><p class="mt-3 border-t border-admin-border pt-2 font-mono text-xs">{{ item.sku }}</p><p v-if="item.cogs_amount !== undefined" class="mt-1 font-mono text-[11px] text-admin-neutral">{{ item.unit_cost_snapshot === null ? t('fulfillment.costUnavailable') : `${item.cost_currency} ${item.unit_cost_snapshot} · ${t('fulfillment.cogs')} ${item.cost_currency} ${item.cogs_amount}` }}</p></article></div>
            </div>
            <aside><p class="admin-label text-admin-secondary">{{ t('fulfillment.historySection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('fulfillment.history') }}</h2><ol class="admin-card mt-4 divide-y divide-admin-border px-4"><li v-for="entry in fulfillment.history" :key="entry.id" class="py-3"><div class="flex flex-wrap items-center gap-2"><StatusBadge v-if="entry.from_status" :status="entry.from_status" /><span v-else class="font-mono text-[10px] text-admin-neutral">{{ t('fulfillment.createdState') }}</span><span aria-hidden="true">→</span><StatusBadge :status="entry.to_status" /></div><p class="mt-2 text-xs text-admin-neutral">{{ formatDate(entry.created_at) }} · {{ entry.actor ?? t('fulfillment.systemActor') }}</p><p v-if="entry.reason" class="mt-1 text-xs">{{ entry.reason }}</p></li></ol></aside>
        </section>

        <section class="admin-card p-4"><p class="admin-label text-admin-secondary">{{ t('fulfillment.traceSection') }}</p><h2 class="mt-1 text-base font-semibold">{{ t('fulfillment.reservations') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('fulfillment.reservationHelp') }}</p><ul class="mt-3 grid gap-2 sm:grid-cols-2"><li v-for="item in fulfillment.items" :key="`reservation-${item.id}`" class="min-w-0 rounded-md border border-admin-border bg-admin-canvas p-3"><p class="font-mono text-xs font-semibold">{{ item.sku }} · {{ t('fulfillment.quantityShort', { count: item.quantity }) }}</p><p class="mt-1 break-all font-mono text-[10px] text-admin-neutral">{{ item.inventory_reservation_id }}</p></li></ul></section>

        <section><div><p class="admin-label text-admin-secondary">{{ t('fulfillment.shippingSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('fulfillment.shipments') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('fulfillment.shipmentHelp') }}</p></div>
            <form v-if="capabilities.create_shipment" class="admin-card mt-4 grid gap-3 p-4 sm:grid-cols-2" @submit.prevent="createShipment"><label class="grid gap-1.5 text-xs font-medium">{{ t('fulfillment.carrier') }}<input v-model="shipmentForm.carrier_name" maxlength="120" class="admin-control px-3 text-sm" /></label><label class="grid gap-1.5 text-xs font-medium">{{ t('fulfillment.service') }}<input v-model="shipmentForm.service_name" maxlength="120" class="admin-control px-3 text-sm" /></label><label class="grid gap-1.5 text-xs font-medium">{{ t('fulfillment.trackingNumber') }}<input v-model="shipmentForm.tracking_number" maxlength="160" class="admin-control px-3 font-mono text-sm" /></label><label class="grid gap-1.5 text-xs font-medium">{{ t('fulfillment.trackingUrl') }}<input v-model="shipmentForm.tracking_url" type="url" maxlength="2048" class="admin-control px-3 text-sm" placeholder="https://" /></label><div class="sm:col-span-2"><FieldError :message="localizedError(shipmentForm.errors.carrier_name ?? shipmentForm.errors.service_name ?? shipmentForm.errors.tracking_number ?? shipmentForm.errors.tracking_url ?? errors.shipment)" /><button :disabled="shipmentForm.processing" class="mt-2 w-full rounded-md bg-admin-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50 sm:w-auto">{{ shipmentForm.processing ? t('fulfillment.processing') : t('fulfillment.createShipment') }}</button></div></form>
            <div v-if="fulfillment.shipments.length" class="mt-4 grid gap-4"><article v-for="shipment in fulfillment.shipments" :key="shipment.id" class="admin-card p-4"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="truncate text-base font-semibold">{{ shipment.carrier_name ?? t('fulfillment.manualShipment') }}</p><p v-if="shipment.service_name" class="mt-0.5 text-xs text-admin-neutral">{{ shipment.service_name }}</p><p class="mt-2 break-all font-mono text-xs">{{ shipment.tracking_number ?? t('fulfillment.noTracking') }}</p><a v-if="shipment.tracking_url" :href="shipment.tracking_url" target="_blank" rel="noopener noreferrer" class="admin-link mt-2 inline-flex text-xs">{{ t('fulfillment.openTracking') }}<span class="sr-only"> {{ t('fulfillment.newWindow') }}</span></a></div><StatusBadge :status="shipment.status" /></div>
                    <dl class="mt-4 grid grid-cols-3 gap-px overflow-hidden rounded-md bg-admin-border"><div v-for="date in [{ label: t('fulfillment.readyAt'), value: shipment.ready_at }, { label: t('fulfillment.shippedAt'), value: shipment.shipped_at }, { label: t('fulfillment.deliveredAt'), value: shipment.delivered_at }]" :key="date.label" class="min-w-0 bg-admin-canvas p-2.5"><dt class="admin-label truncate">{{ date.label }}</dt><dd class="mt-1 text-[10px] text-admin-neutral">{{ formatDate(date.value) }}</dd></div></dl>
                    <div v-if="shipment.can_ready || shipment.can_ship || shipment.can_deliver || shipment.can_cancel" class="mt-4 grid gap-2 sm:flex"><button v-if="shipment.can_ready" :disabled="Boolean(activeAction)" class="rounded-md border border-admin-border-strong px-3 py-2 text-xs font-semibold disabled:opacity-50" @click="shipmentAction(shipment, 'ready')">{{ t('fulfillment.markReady') }}</button><button v-if="shipment.can_ship" :disabled="Boolean(activeAction)" class="rounded-md border border-admin-success-border bg-admin-success-bg px-3 py-2 text-xs font-semibold text-admin-success disabled:opacity-50" @click="shipmentAction(shipment, 'ship')">{{ t('fulfillment.markShipped') }}</button><button v-if="shipment.can_deliver" :disabled="Boolean(activeAction)" class="rounded-md bg-admin-primary px-3 py-2 text-xs font-semibold text-white disabled:opacity-50" @click="shipmentAction(shipment, 'deliver')">{{ t('fulfillment.markDelivered') }}</button><button v-if="shipment.can_cancel" type="button" class="rounded-md border border-admin-danger-border px-3 py-2 text-xs font-semibold text-admin-danger" @click="openShipmentCancellation(shipment)">{{ t('fulfillment.cancelShipment') }}</button></div>
                    <form v-if="cancellingShipment === shipment.id" class="mt-4 rounded-md border border-admin-danger-border bg-admin-danger-bg p-3" @submit.prevent="cancelShipment(shipment)"><label class="grid gap-1.5 text-xs font-medium text-admin-danger">{{ t('fulfillment.cancellationReason') }}<textarea v-model="shipmentCancelForm.reason" required maxlength="500" class="admin-control min-h-20 p-3 text-admin-text" /></label><FieldError :message="localizedError(shipmentCancelForm.errors.reason ?? errors.shipment)" /><div class="mt-3 grid grid-cols-2 gap-2 sm:flex"><button type="button" class="rounded-md border border-admin-border-strong bg-white px-3 py-2 text-xs font-semibold" @click="cancellingShipment = null">{{ t('common.cancel') }}</button><button :disabled="shipmentCancelForm.processing" class="rounded-md bg-admin-danger px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">{{ t('fulfillment.confirmCancellation') }}</button></div></form>
                    <div v-if="shipment.history.length" class="mt-4 border-t border-admin-border pt-4"><p class="admin-label">{{ t('fulfillment.shipmentHistory') }}</p><ol class="mt-2 grid gap-2"><li v-for="entry in shipment.history" :key="entry.id" class="text-xs"><span class="font-mono font-semibold">{{ entry.from_status ? t(`status.${entry.from_status}`) : t('fulfillment.createdState') }} → {{ t(`status.${entry.to_status}`) }}</span><span class="text-admin-neutral"> · {{ formatDate(entry.created_at) }} · {{ entry.actor ?? t('fulfillment.systemActor') }}</span><p v-if="entry.reason" class="mt-0.5 text-admin-text-secondary">{{ entry.reason }}</p></li></ol></div>
                </article></div>
            <EmptyState v-else class="mt-4" :title="t('fulfillment.noShipment')" :description="capabilities.create_shipment ? t('fulfillment.noShipmentCreateHelp') : t('fulfillment.noShipmentHelp')" />
        </section>

        <section v-if="fulfillment.started_at || fulfillment.completed_at || fulfillment.cancelled_at" class="admin-card p-4"><p class="admin-label text-admin-secondary">{{ t('fulfillment.datesSection') }}</p><h2 class="mt-1 text-base font-semibold">{{ t('fulfillment.operationalDates') }}</h2><dl class="mt-3 grid gap-3 sm:grid-cols-3"><div><dt class="admin-label">{{ t('fulfillment.startedAt') }}</dt><dd class="mt-1 text-xs">{{ formatDate(fulfillment.started_at) }}</dd></div><div><dt class="admin-label">{{ t('fulfillment.completedAt') }}</dt><dd class="mt-1 text-xs">{{ formatDate(fulfillment.completed_at) }}</dd></div><div><dt class="admin-label">{{ t('fulfillment.cancelledAt') }}</dt><dd class="mt-1 text-xs">{{ formatDate(fulfillment.cancelled_at) }}</dd></div></dl><p v-if="fulfillment.cancellation_reason" class="mt-3 border-t border-admin-border pt-3 text-xs"><strong>{{ t('fulfillment.cancellationReason') }}:</strong> {{ fulfillment.cancellation_reason }}</p></section>

        <form v-if="capabilities.cancel" class="rounded-lg border border-admin-danger-border bg-admin-danger-bg p-4" @submit.prevent="cancelFulfillment"><p class="admin-label text-admin-danger">{{ t('fulfillment.dangerSection') }}</p><h2 class="mt-1 text-lg font-semibold text-admin-danger">{{ t('fulfillment.cancelFulfillment') }}</h2><p class="mt-1 text-xs text-admin-text-secondary">{{ t('fulfillment.cancelHelp') }}</p><label class="mt-4 grid gap-1.5 text-xs font-medium">{{ t('fulfillment.cancellationReason') }}<textarea v-model="fulfillmentCancelForm.reason" required maxlength="500" class="admin-control min-h-24 p-3" /></label><FieldError :message="localizedError(fulfillmentCancelForm.errors.reason ?? errors.fulfillment)" /><button :disabled="fulfillmentCancelForm.processing" class="mt-3 w-full rounded-md border border-admin-danger-border bg-white px-4 py-2.5 text-sm font-semibold text-admin-danger disabled:opacity-50 sm:w-auto">{{ fulfillmentCancelForm.processing ? t('fulfillment.processing') : t('fulfillment.cancelFulfillment') }}</button></form>
    </div></AdminLayout>
</template>
